118		}
119		// return reader to start after it has been read in analyzer
120		if _, err := r.Seek(0, io.SeekStart); err != nil {
121			return "", xerrors.Errorf("unable to seek: %w", err)
122		}
123	
124		return digest.CalcSHA1(r)
125	}
